<div class="page-heading"><div><h1>Quản lý tài khoản & phân quyền</h1><p>Quản lý thông tin người dùng, vai trò và trạng thái truy cập hệ thống.</p></div><button class="btn btn-primary" onclick="document.getElementById('account-form').scrollIntoView({behavior:'smooth'})">＋ Thêm tài khoản</button></div><div class="panel"><form class="filters" method="get"><div class="field search"><label>Tìm kiếm</label><input class="input" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Tên đăng nhập hoặc họ tên..."></div><div class="field"><label>Vai trò</label><select class="select" name="role"><option value="">Tất cả vai trò</option><?php foreach($roles as $r):?><option value="<?=$r['MaVaiTro']?>" <?=$role===$r['MaVaiTro']?'selected':''?>><?=htmlspecialchars($r['TenVaiTro'])?></option><?php endforeach?></select></div><div class="field"><label>Trạng thái</label><select class="select" name="status"><option value="">Tất cả</option><option value="ACTIVE" <?=$status==='ACTIVE'?'selected':''?>>Hoạt động</option><option value="LOCKED" <?=$status==='LOCKED'?'selected':''?>>Tạm khóa</option></select></div><button class="btn btn-primary" style="align-self:end">Tìm kiếm</button></form><div class="table-wrap"><table><thead><tr><th>STT</th><th>Tên đăng nhập</th><th>Họ và tên</th><th>Vai trò</th><th>Trạng thái</th><th>Đăng nhập gần nhất</th><th>Thao tác</th></tr></thead><tbody><?php if(!$accounts):?><tr><td colspan="7" style="text-align:center;padding:35px">Không tìm thấy tài khoản.</td></tr><?php endif?><?php foreach($accounts as $i=>$a):?><tr><td><?=$i+1?></td><td><b><?=htmlspecialchars($a['TenDangNhap'])?></b></td><td><?=htmlspecialchars($a['HoTen'])?></td><td><?=htmlspecialchars($a['TenVaiTro'])?></td><td><span class="badge <?=$a['TrangThai']==='ACTIVE'?'green':'red'?>"><?=$a['TrangThai']==='ACTIVE'?'Hoạt động':'Tạm khóa'?></span></td><td><?=htmlspecialchars($a['LanDangNhapCuoi']??'—')?></td><td><div class="actions"><button class="icon-btn" title="Sửa" onclick='editAccount(<?=json_encode($a,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>✎</button><?php if($a['MaTaiKhoan']!==Auth::user()['MaTaiKhoan']&&$a['TrangThai']==='ACTIVE'):?><form method="post" action="<?=BASE_URL?>/accounts/delete" onsubmit="return confirm('Khóa tài khoản này?')"><input type="hidden" name="id" value="<?=$a['MaTaiKhoan']?>"><button class="icon-btn" title="Khóa">▣</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></div><div class="panel" id="account-form"><div class="panel-title"><h2 id="form-title">Thêm tài khoản</h2><span class="muted">* Bắt buộc</span></div><form method="post" action="<?=BASE_URL?>/accounts/save"><input type="hidden" name="id" id="a-id"><div class="form-grid"><div class="field"><label>Tên đăng nhập *</label><input class="input" name="username" id="a-username" required></div><div class="field"><label>Mật khẩu <span id="pw-required">*</span></label><input class="input" type="password" name="password" id="a-password" minlength="8" placeholder="Ít nhất 8 ký tự"></div><div class="field"><label>Họ và tên *</label><input class="input" name="name" id="a-name" required></div><div class="field"><label>Vai trò *</label><select class="select" name="role" id="a-role" required><?php foreach($roles as $r):?><option value="<?=$r['MaVaiTro']?>"><?=htmlspecialchars($r['TenVaiTro'])?></option><?php endforeach?></select></div><div class="field"><label>Email</label><input class="input" type="email" name="email" id="a-email"></div><div class="field"><label>Số điện thoại</label><input class="input" name="phone" id="a-phone"></div><div class="field"><label>Trạng thái *</label><select class="select" name="status" id="a-status"><option value="ACTIVE">Hoạt động</option><option value="LOCKED">Tạm khóa</option></select></div></div><div class="form-actions"><button class="btn btn-light" type="button" onclick="resetAccount()">Làm mới</button><button class="btn btn-primary">Lưu tài khoản</button></div></form></div><script>function editAccount(a){document.getElementById('form-title').innerText='Cập nhật tài khoản';document.getElementById('a-id').value=a.MaTaiKhoan;document.getElementById('a-username').value=a.TenDangNhap;document.getElementById('a-name').value=a.HoTen;document.getElementById('a-role').value=a.MaVaiTro;document.getElementById('a-email').value=a.Email||'';document.getElementById('a-phone').value=a.SoDienThoai||'';document.getElementById('a-status').value=a.TrangThai;document.getElementById('a-password').required=false;document.getElementById('pw-required').innerText='';document.getElementById('account-form').scrollIntoView({behavior:'smooth'})}function resetAccount(){document.querySelector('#account-form form').reset();document.getElementById('a-id').value='';document.getElementById('form-title').innerText='Thêm tài khoản';document.getElementById('a-password').required=true;document.getElementById('pw-required').innerText='*'}</script>